const calculatePurchaseOrderReceiptStatus = `-- name: CalculatePurchaseOrderReceiptStatus :one
SELECT CASE
    WHEN COUNT(*) FILTER (
        WHERE poi.status NOT IN ('CANCELLED', 'RECEIVED', 'OVER_RECEIVED', 'FULFILLED')
    ) = 0 THEN 'COMPLETED'::purchase_order_status
    WHEN COUNT(*) FILTER (
        WHERE poi.status IN ('PARTIAL_RECEIVED', 'RECEIVED', 'OVER_RECEIVED', 'FULFILLED')
    ) > 0 THEN 'PARTIALLY_RECEIVED'::purchase_order_status
    ELSE 'VERIFIED'::purchase_order_status
END AS status
FROM purchase_order_items poi
WHERE poi.purchase_order_id = $1
`

func (q *Queries) CalculatePurchaseOrderReceiptStatus(ctx context.Context, purchaseOrderID pgtype.UUID) (PurchaseOrderStatus, error) {
	row := q.db.QueryRow(ctx, calculatePurchaseOrderReceiptStatus, purchaseOrderID)
	var status PurchaseOrderStatus
	err := row.Scan(&status)
	return status, err
}

